command:
log=~/linux-desktop/logs/komla.log; for i in $(seq 240); do
  grep -q -i -E 'start electron app|electron app started' "$log" 2>/dev/null && { sleep 20; break; }
  ~/linux-desktop/linux-desktop.sh status | grep -q 'komla    running' || { echo "komla exited"; break; }
  sleep 1
done; tail -40 "$log"

F=/tmp/scratch/scratchpad && pgrep -af node_modules/playwright/lib/worker | head -3; {
npm test > $F/npm-test3.log 2>&1; echo "NPM_TEST_EXIT $?";
npm run lint:react > $F/lint-react3.log 2>&1; echo "LINT_REACT_EXIT $?";
npx tsc --noEmit -p tsconfig.web.json > $F/tsc-web-v2.txt 2>&1; echo "TSC_WEB errors: $(grep -c 'error TS' $F/tsc-web-v2.txt) (head $(grep -c 'error TS' $F/tsc-web-head.txt))";
npx tsc --noEmit -p tsconfig.node.json > $F/tsc-node-v2.txt 2>&1; echo "TSC_NODE errors: $(grep -c 'error TS' $F/tsc-node-v2.txt) (head $(grep -c 'error TS' $F/tsc-node-head.txt))";
xvfb-run -a --server-args="-screen 0 1920x1080x24" npx playwright test --config e2e/playwright.config.ts > $F/e2e3.log 2>&1; echo "E2E_EXIT $?";
git checkout -- package-lock.json 2>/dev/null; } > $F/checks3.log 2>&1; cat $F/checks3.log; grep -E "Test Files|Tests " $F/npm-test3.log | tail -2; grep -E "passed|failed|flaky" $F/e2e3.log | tail -4

python3 -I - <<'EOF'
…
EOF
F=/tmp/scratch/scratchpad; pgrep -af node_modules/playwright/lib/worker | head -2; {
npm test > $F/npm-test4.log 2>&1; echo "NPM_TEST_EXIT $?";
npm run lint:react > $F/lint-react4.log 2>&1; echo "LINT_REACT_EXIT $?";
npx tsc --noEmit -p tsconfig.web.json > $F/tsc-web-v3.txt 2>&1; echo "TSC_WEB errors: $(grep -c 'error TS' $F/tsc-web-v3.txt) (head $(grep -c 'error TS' $F/tsc-web-head.txt))";
npx tsc --noEmit -p tsconfig.node.json > $F/tsc-node-v3.txt 2>&1; echo "TSC_NODE errors: $(grep -c 'error TS' $F/tsc-node-v3.txt) (head $(grep -c 'error TS' $F/tsc-node-head.txt))";
xvfb-run -a --server-args="-screen 0 1920x1080x24" npx playwright test --config e2e/playwright.config.ts e2e/*.test.ts > $F/e2e4.log 2>&1; echo "E2E_EXIT $?";
git checkout -- package-lock.json 2>/dev/null; } > $F/checks4.log 2>&1; cat $F/checks4.log; grep -E "Test Files|Tests " $F/npm-test4.log | tail -2; grep -E "^\s+[0-9]+ (passed|failed|flaky)" $F/e2e4.log

F=/tmp/scratch/scratchpad && pgrep -af node_modules/playwright/lib/worker | head -2; {
