npx tsc --noEmit -p tsconfig.web.json > $F/tsc-web-v4.txt 2>&1; echo "TSC_WEB errors: $(grep -c 'error TS' $F/tsc-web-v4.txt) (head $(grep -c 'error TS' $F/tsc-web-head.txt))";
